  "butterflyBullName": "強気バタフライ",
  "butterflyBullDesc": "ガートレーに似ているが、DはXを超えてXAの127.2%または161.8%まで伸びる。起点を超える伸展は、より極端な反転とより強い反発の可能性を示す。",
  "butterflyBullStep1": "XAの脚を特定;BはXAの78.6%を戻すべき",
  "butterflyBullStep2": "CはABの38.2〜88.6%を戻す",
  "butterflyBullStep3": "DはXAの127.2%または161.8%まで伸びる(Xを超えて)",
  "butterflyBullStep4": "強気の確認足を伴ってDで買い",
  "butterflyBullStep5": "損切りはDの安値の下。TP1=CDの61.8%、TP2=CDの127.2%",
  "butterflyBullReliability": "中",
  "butterflyBearName": "弱気バタフライ",
  "butterflyBearDesc": "反転バタフライ。DはXを下抜けてXAの127.2%または161.8%まで伸びる。パターン起点の下のPRZで極端な弱気反転を示す。",
  "butterflyBearStep1": "弱気のXAの脚を特定;BはXAの78.6%を戻す",
