  "batBullName": "強気バット(コウモリ)",
  "batBullDesc": "最も精密なハーモニックパターン。BはXAの38.2〜50%しか戻さない(ガートレーより浅い)。DはXAの88.6%リトレースメントにある。非常にタイトなフィボナッチの整合が高い特異性を生む。",
  "batBullStep1": "BはXAの38.2%〜50%を戻す必要(重要な差別化点)",
  "batBullStep2": "CはABの38.2〜88.6%を戻す",
  "batBullStep3": "DはXAのちょうど88.6%リトレースメント",
  "batBullStep4": "Dで買い。強気のピンバーまたは包み足で確認",
  "batBullStep5": "損切りはXの下。TP1=DからXAの38.2%、TP2=DからXAの61.8%",
  "batBullReliability": "高",
  "batBearName": "弱気バット(コウモリ)",
  "batBearDesc": "反転バットパターン。浅いBの戻し(XAの38.2〜50%)とXAの88.6%にあるDにより、最も精密で信頼できるハーモニック売りセットアップの一つとなる。",
  "batBearStep1": "BはXAの38.2%〜50%を戻す必要",
  "batBearStep2": "CはABの38.2〜88.6%を戻す",
  "batBearStep3": "DはXAのちょうど88.6%リトレースメント",
  "batBearStep4": "Dで売り。弱気の否定足で確認",
  "batBearStep5": "損切りはXの上。TP1=DからXAの38.2%、TP2=DからXAの61.8%",
  "batBearReliability": "高",
  "crabBullName": "強気クラブ(カニ)",
  "crabBullDesc": "最も極端なハーモニックパターン。DはXAの161.8%まで伸び——当初の値動きをはるかに超える。BはXAの38.2〜61.8%を戻す。極端な伸展はしばしば市場の主要な転換点を示す。",
  "crabBullStep1": "BはXAの38.2〜61.8%を戻す",
  "crabBullStep2": "CはABの38.2〜88.6%を戻す",
  "crabBullStep3": "DはXAの161.8%まで伸びる(非常に伸展)",
  "crabBullStep4": "Dで買い。極端な伸展のためポジションサイズを小さく",
  "crabBullStep5": "損切りはDの下。TP1=DからXAの61.8%。TP2=DからXAの100%",
  "crabBullReliability": "中",
  "crabBearName": "弱気クラブ(カニ)",
  "crabBearDesc": "反転クラブで、DはXAの下方161.8%延伸にある。極端な弱気の転換点を示す。極端な伸展により高いリスクリワードだが、厳格なリスク管理を要する。",
  "crabBearStep1": "BはXAの38.2〜61.8%を戻す",
  "crabBearStep2": "CはABの38.2〜88.6%を戻す",
  "crabBearStep3": "DはXAの161.8%まで伸びる(極端な伸展)",
  "crabBearStep4": "Dで売り。伸びた値動きのためポジションサイズを縮小",
  "crabBearStep5": "損切りはDの上。TP1=CDの61.8%リトレース。TP2=Aの水準",
  "crabBearReliability": "中",
  "sharkName": "シャーク(サメ)",
  "sharkDesc": "0-X-A-B-C構造(Dなし)の比較的新しいハーモニックパターン。CはOX伸展の88.6〜113%、ABの161.8〜224%で形成。Cで逆張りエントリーし、素早い反転を狙う。方向により強気にも弱気にもなる。",
  "sharkStep1": "0-Xのインパルスの脚を特定",
  "sharkStep2": "AはOXの戻し、BはOXの113%まで伸びる",
  "sharkStep3": "CはOからOXの88.6〜113%まで伸びる",
  "sharkStep4": "Cで逆張りエントリー(ここがPRZ)",
  "sharkStep5": "損切りはCの向こう。TP=BCの50%リトレース(素早い目標)",
  "sharkReliability": "中",
  "cypherBullName": "強気サイファー",
  "cypherBullDesc": "X-A-B-C-Dのハーモニックで、CはXAの113〜141.4%まで伸びる。DはXCの78.6%で完成。CがAを超えて伸びる点がガートレーとの違いで、より広い強気反転ゾーンを作る。",
  "cypherBullStep1": "BはXAの38.2〜61.8%を戻す",
  "cypherBullStep2": "CはXAの113〜141.4%まで伸びる(Aを超えて)",
  "cypherBullStep3": "DはXCの78.6%まで戻す",
  "cypherBullStep4": "強気のローソク足確認を伴ってDで買い",
  "cypherBullStep5": "損切りはXの下。TP1=CDの38.2%、TP2=CDの61.8%",
  "cypherBullReliability": "中",
  "cypherBearName": "弱気サイファー",
  "cypherBearDesc": "反転サイファー。CはAを下抜けてXAの113〜141.4%まで伸び、DはXCの78.6%にある。反転トレードとして弱気の確認を伴ってDで売り。",
  "cypherBearStep1": "BはXAの38.2〜61.8%を戻す",
  "cypherBearStep2": "CはXAの113〜141.4%まで伸びる(Aの下)",
  "cypherBearStep3": "DはXCの78.6%まで戻す",
  "cypherBearStep4": "弱気のローソク足確認を伴ってDで売り",
